/* Additive story workbench. All durable edits use the existing domain command API. */
export function createWorkbench(api){
 const esc=api.e, ico=api.icon, btn=(t,a,x='',k='secondary')=>api.button(t,'wb-'+a,x,k);
 let view='canvas',mode='heard',project='project_rowan_reach',storyId='story_rowan_return',eventId='se_retreat',occId='occ_return',ref=null,refLoading=false,results=null,query='',lastRender=null,previewAudio=null,loop=null;
 const w=()=>api.state().workbench||{}, current=()=>w().stories?.find(s=>s.id===storyId)||w().stories?.[0], byId=id=>Object.values(w()).filter(Array.isArray).flat().find(x=>x.id===id);
 const time=n=>`${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}`;
 const nice=s=>String(s||'').replaceAll('_',' '), fmt=n=>Math.round(n*100);
 const motif=id=>w().motifs.find(m=>m.id===id), instrument=id=>api.instruments().find(i=>i.id===id)?.name||id;
 const pill=(t,cls='')=>`<span class="wb-badge ${cls}">${esc(t)}</span>`;
 const colors=['#e8ba82','#a3cbbc','#aabfd8','#c9add7','#d2ca93','#95bbd0'];
 const fitLabel=(title,width)=>{const n=Math.max(4,Math.floor((width-15)/5.7));return title.length>n?title.slice(0,n-1)+'…':title;};
 const color=id=>colors[Math.max(0,w().motifs.findIndex(m=>m.id===id))%colors.length];
 const opts=(rows,val,label='title')=>rows.map(x=>`<option value="${esc(x.id)}" ${x.id===val?'selected':''}>${esc(x[label])}</option>`).join('');
 const descendants=id=>{const ids=new Set([id]);let changed=true;while(changed){changed=false;for(const p of w().projects||[])if(ids.has(p.parent_id)&&!ids.has(p.id)){ids.add(p.id);changed=true;}}return ids;};
 function hierarchy(){const projects=w().projects||[];function branch(parent,depth=0){return projects.filter(p=>p.parent_id===parent).map(p=>`<button class="wb-tree-node ${p.id===project?'selected':''}" style="--depth:${depth}" data-action="wb-project" data-id="${esc(p.id)}">${ico(depth?'layers':'book')}<span>${esc(p.title)}<small>${esc(p.kind)}</small></span></button>${branch(p.id,depth+1)}`).join('');}return branch(null);}
 function navigation(){return `<div class="wb-subnav">${[['canvas','Story canvas'],['motifs','Motif atlas'],['discover','Discover & keep'],['projects','Worlds & works'],['experiments','Pipes & experiments']].map(([id,title])=>`<button class="${view===id?'selected':''}" data-action="wb-view" data-id="${id}">${title}</button>`).join('')}</div>`;}
 function welcome(){return `<section class="wb-welcome"><span class="eyebrow">MEATYMUSIC + PIPES / REVIEW BUILD 0.4</span><h1>Music you can think in.</h1><p>Keep a feeling. Trace a returning melody. Paint the story before you write its notes.</p><div class="wb-welcome-arc"><svg viewBox="0 0 820 170" aria-label="Illustrative reach, retreat, and renewed ascent"><path d="M10 140 C100 140 115 48 195 55 S300 148 390 95 S468 150 505 105 S590 -6 660 35 S735 133 810 125" fill="none" stroke="currentColor" stroke-width="3"/><path d="M10 156H810" stroke="currentColor" opacity=".14"/></svg></div><div class="wb-welcome-cards"><article><b>The Long Becoming</b><p>World → Rowan Reach → cues → performances, with motifs shared by reference.</p></article><article><b>One real beginning</b><p>Your complete 3:14.8 reference, raw MIDI and listening notes. No simulated analysis or newly generated song.</p></article><article><b>Two honest surfaces</b><p>What you heard and what you intend to create—linked, never silently treated as the same thing.</p></article></div>${btn('Open the Rowan Reach study','seed','','primary')}<p class="micro">Imports bundled private source assets into this local workspace. Nothing is sent to a provider.</p></section>`;}
 function top(){const p=byId(project)||w().projects[0];return `<section class="wb-head"><div><span class="eyebrow">THE MUSICAL WORKBENCH / ${esc(p?.kind||'project')}</span><h1>${esc(p?.title||'Your musical worlds')}</h1><p>${esc(p?.summary||'Ideas can stay unfinished here.')}</p></div><div class="wb-head-actions">${btn(ico('plus')+' New story','new-story')}${btn(ico('note')+' Catch a thought','capture','','primary')}</div></section>${navigation()}`;}
 function referencePanel(){return `<div class="wb-reference-bar"><div><span class="eyebrow">PRESERVED REFERENCE / LOCAL AUDIO</span><h3>Above the Rowan Canopy</h3><p>3:14.8 · original unchanged · accepted by listening, not a verified score</p></div><div>${btn(ico('play')+' Whole song','play','data-start="0" data-end="194.8"')}${btn('First promise','play','data-start="25" data-end="55"')}${btn('Complete return','play','data-start="85" data-end="112"')}</div></div>`;}
 function waveform(){if(!ref)return '<div class="wb-loading">Reading the bundled source receipt…</div>';const peaks=ref.waveform.peaks;const paths=peaks.map((p,i)=>{let x=20+i*960/peaks.length;return `M${x.toFixed(1)} ${(66-p*48).toFixed(1)}v${(p*96).toFixed(1)}`;}).join(' ');return `<div class="wb-wave"><svg viewBox="0 0 1000 145" role="img" aria-label="Measured amplitude overview with human-reported passage windows"><rect x="${20+25/194.8*960}" y="7" width="${30/194.8*960}" height="116" fill="#e8ba82" opacity=".10"/><rect x="${20+85/194.8*960}" y="7" width="${27/194.8*960}" height="116" fill="#a3cbbc" opacity=".12"/><path d="${paths}" stroke="#7a9289" stroke-width="1"/><line id="wb-wave-head" x1="20" x2="20" y1="7" y2="123" stroke="#edece2" stroke-width="1.5" opacity="0"/><path d="M${20+40/194.8*960} 22 Q${20+69/194.8*960} -6 ${20+98/194.8*960} 22" fill="none" stroke="#e8ba82" stroke-width="1.5" stroke-dasharray="4 4"/><text x="${20+62/194.8*960}" y="15" fill="#e8ba82" font-size="10">recalls · Nick’s listening note</text>${[0,30,60,90,120,150,180].map(t=>`<text x="${20+t/194.8*960}" y="139" fill="#93a7a0" font-size="10">${time(t)}</text>`).join('')}</svg><span>Waveform = measured amplitude. The callback link = human interpretation.</span></div>`;}
 function piano(){if(!ref)return '';const a=85,b=112;const ns=ref.midi.notes.filter(n=>n.end>a&&n.start<b);const lo=52,hi=85;return `<section class="wb-panel wb-midi"><div class="wb-panel-title"><div><span class="eyebrow">MACHINE CANDIDATE / NOT A VERIFIED SOLO LINE</span><h3>Raw MIDI beneath the whole return</h3></div>${pill('Origin preserved · 0:00','candidate')}</div><svg viewBox="0 0 1000 195" role="img" aria-label="Uncorrected Basic Pitch note events from 1:25 to 1:52">${[55,60,65,70,75,80].map(n=>`<line x1="50" y1="${15+(hi-n)*4.6}" x2="980" y2="${15+(hi-n)*4.6}" stroke="#2d3c38"/><text x="12" y="${19+(hi-n)*4.6}" font-size="10" fill="#93a7a0">${n}</text>`).join('')}${ns.map(n=>`<rect x="${50+(Math.max(a,n.start)-a)/(b-a)*930}" y="${15+(hi-n.pitch)*4.6}" width="${Math.max(1,(Math.min(b,n.end)-Math.max(a,n.start))/(b-a)*930)}" height="3.6" fill="#c9add7" opacity=".8"><title>${esc(n.name)} · ${n.start.toFixed(2)}–${n.end.toFixed(2)}s</title></rect>`).join('')}<line id="wb-midi-head" x1="50" x2="50" y1="12" y2="175" stroke="#edece2" opacity="0"/>${[85,90,95,100,105,110].map(t=>`<text x="${50+(t-a)/(b-a)*930}" y="186" fill="#93a7a0" font-size="10">${time(t)}</text>`).join('')}</svg><p class="micro">${ref.midi.note_count} raw notes in the full file. Overlaps remain. File tempo is metadata, not the measured tempo of the song. No note event is automatically a motif occurrence.</p></section>`;}
 function heard(){const os=w().occurrences.filter(o=>o.id!=='occ_full'),chosen=byId(occId)||os[0];return `${referencePanel()}${waveform()}<div class="wb-evidence-layout"><section class="wb-panel"><div class="wb-panel-title"><div><span class="eyebrow">RECOGNITION → WITHDRAWAL → CONTINUANCE</span><h3>The passage needs its history</h3></div>${pill('Human listening','heard')}</div><div class="wb-phrase-cards">${os.map(o=>`<button class="wb-phrase ${chosen?.id===o.id?'selected':''}" data-action="wb-occurrence" data-id="${o.id}"><span class="mono">${time(o.start)}–${time(o.end)}</span><strong>${esc(o.title)}</strong><small>${esc(motif(o.motif_id)?.title||'')}</small></button>`).join('')}</div>${piano()}</section><aside class="wb-panel wb-inspector"><span class="eyebrow">LISTENING ANCHOR / APPROXIMATE BOUNDARIES</span><h2>${esc(chosen?.title||'Select a passage')}</h2><p class="wb-quote">${esc(chosen?.note||'')}</p><div class="wb-pills">${pill(nice(chosen?.evidence),'heard')}${pill(nice(chosen?.verification),'candidate')}</div><div class="wb-stack">${btn(ico('play')+' Listen with context','context-play',`data-id="${chosen?.id}"`,'primary')}${btn('Loop selected passage','loop',`data-start="${chosen?.start}" data-end="${chosen?.end}"`)}${btn('Gather its materials','context',`data-id="${chosen?.id}"`)}${btn('Paint a new interpretation','mode','data-id="paint"')}</div><div class="wb-callout"><b>Meaning is not a decibel value.</b><p>The dip can feel like longing without a matching reduction in loudness. Preserve your interpretation beside the signal, not inside it.</p></div><p class="micro">No exact melody match or harmony identification is claimed. The six-note prompt sketch stays separate from this recorded theme.</p></aside></div>`;}
 function storySvg(s){const events=s.events;const lanes=[...new Set(events.map(e=>e.instrument))];const laneY=id=>122+lanes.indexOf(id)*65;const x=v=>135+v*825;let points=events.filter(e=>e.role==='lead'||e.role==='answer').map(e=>[x((e.start+e.end)/2),80-e.level*48]);const curve=points.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');const height=155+lanes.length*65;return `<svg class="wb-story-svg" viewBox="0 0 1000 ${height}" aria-label="Editable musical intent timeline. Drag gestures horizontally, or use the inspector's numeric fields."><defs><marker id="wb-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10" fill="none" stroke="#93a7a0"/></marker></defs><text x="12" y="35" fill="#93a7a0" font-size="11">Drawn emphasis</text><text x="12" y="51" fill="#647d74" font-size="9">intent, not loudness</text><path d="${curve}" fill="none" stroke="#e8ba82" stroke-width="2"/>${points.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="#e8ba82"/>`).join('')}${[0,.25,.5,.75,1].map(p=>`<line x1="${x(p)}" x2="${x(p)}" y1="93" y2="${height-20}" stroke="#2d3c38" stroke-dasharray="3 5"/><text x="${x(p)}" y="${height-4}" fill="#93a7a0" font-size="10">${Math.round(p*100)}%</text>`).join('')}${lanes.map(l=>`<text x="12" y="${laneY(l)+23}" fill="#edece2" font-size="11">${esc(instrument(l))}</text><line x1="135" x2="960" y1="${laneY(l)+48}" y2="${laneY(l)+48}" stroke="#2d3c38"/>`).join('')}${s.relationships.map(r=>{let a=events.find(e=>e.id===r.source_id),b=events.find(e=>e.id===r.target_id);if(!a||!b)return '';let ax=x((a.start+a.end)/2),bx=x((b.start+b.end)/2),ay=laneY(a.instrument),by=laneY(b.instrument);return `<path d="M${ax} ${ay} C${ax} ${Math.min(ay,by)-43} ${bx} ${Math.min(ay,by)-43} ${bx} ${by}" fill="none" stroke="#819c92" opacity=".6" stroke-width="1.1" stroke-dasharray="4 3" marker-end="url(#wb-arrow)"><title>${esc(a.title)} ${esc(nice(r.kind))} ${esc(b.title)}</title></path>`;}).join('')}${events.map(e=>`<g class="wb-stroke ${e.id===eventId?'selected':''}" data-stroke-id="${esc(e.id)}" data-action="wb-event" data-id="${esc(e.id)}" transform="translate(${x(e.start)},${laneY(e.instrument)})"><rect width="${(e.end-e.start)*825}" height="42" rx="7" fill="${color(e.motif_id)}" fill-opacity=".13" stroke="${color(e.motif_id)}" stroke-width="${e.id===eventId?2:1}" stroke-dasharray="${e.locked?'0':'4 2'}"/><text x="8" y="16" fill="${color(e.motif_id)}" font-size="10">${esc(fitLabel(e.title,(e.end-e.start)*825))}</text><text x="8" y="31" fill="#93a7a0" font-size="9">${esc(fitLabel(e.gesture+(e.locked?' · pinned':''),(e.end-e.start)*825))}</text><title>${esc(e.title)} / ${esc(motif(e.motif_id)?.title)} / ${e.start*100}–${e.end*100}%</title></g>`).join('')}</svg>`;}
 function editor(s){const e=s.events.find(x=>x.id===eventId)||s.events[0];if(!e)return `<aside class="wb-panel wb-inspector"><h3>Your canvas is open</h3><p>Add a gesture, choose a voice, and describe what it means. Notes can come later.</p>${btn('Add the first gesture','add-event','','primary')}</aside>`;eventId=e.id;const disabled=e.locked?'disabled':'';return `<aside class="wb-panel wb-inspector"><span class="eyebrow">PAINTED GESTURE / AUTHOR INTENT</span><h2>${esc(e.title)}</h2><p class="micro">These edits change a story draft, never the original recording.</p><label>Phrase title<input id="wb-event-title" value="${esc(e.title)}" ${disabled}></label><label>Motif / idea<select id="wb-event-motif" ${disabled}>${opts(w().motifs,e.motif_id)}</select></label><div class="wb-field-pair"><label>Voice<select id="wb-event-instrument" ${disabled}>${opts(api.instruments(),e.instrument,'name')}</select></label><label>Job<select id="wb-event-role" ${disabled}>${['lead','answer','counterline','foundation','pattern','color','expansion','silence'].map(v=>`<option ${v===e.role?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="wb-field-pair"><label>Start %<input id="wb-event-start" type="number" min="0" max="99" step=".1" value="${fmt(e.start)}" ${disabled}></label><label>End %<input id="wb-event-end" type="number" min="1" max="100" step=".1" value="${fmt(e.end)}" ${disabled}></label></div><div class="wb-field-pair"><label>Gesture<select id="wb-event-gesture" ${disabled}>${['introduce','reach','recall','withdraw','hold','support','rise','release','settle','answer','absence'].map(v=>`<option ${v===e.gesture?'selected':''}>${v}</option>`).join('')}</select></label><label>Drawn emphasis<input id="wb-event-level" type="range" min="0" max="1" step=".05" value="${e.level}" ${disabled}></label></div><label>What should this do?<textarea id="wb-event-note" rows="4" ${disabled}>${esc(e.note)}</textarea></label><div class="wb-pills">${pill(motif(e.motif_id)?.status||'concept','intent')}</div><div class="wb-stack">${e.locked?btn(ico('unlock')+' Unpin explicitly','unlock','','primary'):btn('Save this gesture','save-event','','primary')}${!e.locked?btn('Pin this gesture','pin'):''}${e.source_occurrence_id?btn('Hear the source relationship','context-play',`data-id="${e.source_occurrence_id}"`):''}</div></aside>`;}
 function paint(){const s=current();if(!s)return '<p>Create a story to begin.</p>';return `<div class="wb-story-toolbar"><label>Story draft<select id="wb-story-select">${opts(w().stories, s.id)}</select></label><span>${pill('Relative story position','intent')} ${pill('Revision '+s.revision)}</span><div>${btn('Add gesture','add-event')}${btn('Connect phrases','link-events')}${btn('Branch','branch')}${btn('Prepare creation packet','compile','','primary')}</div></div><div class="wb-paint-layout"><section class="wb-panel wb-canvas-panel"><div class="wb-panel-title"><div><span class="eyebrow">PAINT → STRUCTURE → NOTES → PERFORMANCE</span><h3>Give each idea a voice. Let it return changed.</h3></div></div><div class="wb-canvas-scroll">${storySvg(s)}</div><div class="wb-legend">${[...new Set(s.events.map(e=>e.motif_id))].map(id=>`<span><i style="background:${color(id)}"></i>${esc(motif(id)?.title)}</span>`).join('')}</div><div class="wb-canvas-note">Drag a gesture left or right; use the inspector for precise positions. The dashed curves show phrase relationships. Drawing a rise does not claim notes, harmony, or volume have been rendered.</div><div class="wb-render-controls"><div><b>Bring a note-backed sketch to sound</b><p>Explicit notes → MIDI + a quiet sine-tone preview. Not a realistic instrument performance.</p></div>${btn('Check & render a sketch','render-modal')}${btn('View source-style packet','compile')}</div>${lastRender?`<div class="wb-render-result"><strong>Diagnostic render ready</strong><audio id="wb-preview-audio" controls src="${esc(lastRender.audio)}"></audio><a href="${esc(lastRender.midi)}" download>Download authored MIDI</a><span class="micro">${esc(lastRender.notice)}</span></div>`:''}</section>${editor(s)}</div>`;}
 function canvas(){return `<div class="wb-modebar"><div role="tablist" aria-label="Separate intent from evidence"><button role="tab" aria-selected="${mode==='heard'}" class="${mode==='heard'?'active':''}" data-action="wb-mode" data-id="heard">${ico('headphones')} Listen / evidence</button><button role="tab" aria-selected="${mode==='paint'}" class="${mode==='paint'?'active':''}" data-action="wb-mode" data-id="paint">${ico('spark')} Paint / intent</button></div><span>One musical idea. Distinct kinds of truth.</span></div>${mode==='heard'?heard():paint()}`;}
 function motifs(){return `<div class="wb-section-header"><div><h2>Recognizable ideas, not just note sequences.</h2><p>Melody, rhythm, texture and an expressive relationship can each be a motif.</p></div>${btn('Create a motif','new-motif','','primary')}</div><div class="wb-motif-grid">${w().motifs.map((m,i)=>{const appearances=w().occurrences.filter(o=>o.motif_id===m.id&&o.id!=='occ_full');const plans=w().stories.flatMap(s=>s.events.filter(e=>e.motif_id===m.id).map(e=>({story:s,event:e})));return `<article class="wb-panel wb-motif-card" style="--motif:${color(m.id)}"><span class="eyebrow">${esc(nice(m.kind))}</span><h2>${esc(m.title)}</h2><p>${esc(m.meaning)}</p>${m.symbolic?`<div class="wb-note-notation">${m.symbolic.pitches.map(p=>`<span>${esc(['C','C♯','D','E♭','E','F','F♯','G','A♭','A','B♭','B'][p%12])}<small>${Math.floor(p/12)-1}</small></span>`).join('')}</div>`:`<div class="wb-abstract-motif">${m.kind==='expressive_arc'?'reach → retreat → hold → return':'Audio identity selected · exact notation pending'}</div>`}<div class="wb-pills">${pill(nice(m.status),'candidate')}${m.tags.map(t=>pill(t)).join('')}</div><div class="wb-usage"><b>Where it appears</b>${appearances.map(o=>`<button data-action="wb-occurrence" data-id="${o.id}">${time(o.start)} · ${esc(o.title)} <small>reported in reference</small></button>`).join('')}${plans.slice(0,3).map(({story,event})=>`<button data-action="wb-open-story-event" data-story="${story.id}" data-event="${event.id}">${esc(event.title)} · ${esc(instrument(event.instrument))}<small>planned in ${esc(story.title)}</small></button>`).join('')}${!appearances.length&&!plans.length?'<p class="micro">An idea can be kept before it belongs to a song.</p>':''}</div>${btn('Gather motif context','context',`data-id="${m.id}"`)}</article>`;}).join('')}</div>`;}
 function discover(){const captures=w().captures.filter(c=>!c.project_id||descendants(project).has(c.project_id));return `<section class="wb-discover-head"><span class="eyebrow">YOU DO NOT NEED THE RIGHT MUSICAL WORD</span><h2>Start with what you remember.</h2><div class="wb-searchbox">${ico('search')}<input id="wb-search" value="${esc(query)}" placeholder="A dip that pulls at the heart… wood and glass… a cello answer…"><button data-action="wb-search">Explore</button></div><div class="wb-search-seeds">${['yearning hope','home','fiddle','callback','craft','world'].map(q=>`<button data-action="wb-search-seed" data-query="${q}">${q}</button>`).join('')}</div><p class="micro">Local text + curated synonym matching. Explanations show why an item appeared; no hidden model analysis.</p></section>${results?`<section class="wb-results"><h3>${results.total} relevant materials</h3>${results.results.map(r=>`<button class="wb-result" data-action="wb-result" data-id="${r.id}" data-kind="${r.kind}"><span>${pill(r.kind)}<b>${esc(r.title)}</b><small>${esc(r.why)}</small></span>${ico('chevron')}</button>`).join('')}${!results.total?'<p>No local match yet. Keep the thought rather than inventing a result.</p>':''}</section>`:''}<div class="wb-section-header"><div><h2>Keep the spark. Decide later.</h2><p>No project, task, theory vocabulary or action commitment required.</p></div>${btn('Catch a thought','capture','','primary')}</div><div class="wb-capture-grid">${captures.map(c=>`<article class="wb-panel"><span class="eyebrow">${esc(nice(c.kind))} / ${esc(c.status)}</span><p class="wb-quote">${esc(c.text)}</p><small>${esc(c.source)}</small><div class="wb-pills">${c.tags.map(t=>pill(t)).join('')}</div>${btn('Gather context','context',`data-id="${c.id}"`)}</article>`).join('')}</div>`;}
 function projects(){const scope=descendants(project),works=w().works.filter(x=>scope.has(x.project_id));return `<div class="wb-project-layout"><aside class="wb-panel"><span class="eyebrow">NESTED CONTEXT / ONE CANONICAL HOME</span>${hierarchy()}${btn('New nested project','new-project')}</aside><section><div class="wb-section-header"><div><h2>Works in this world</h2><p>A cue owns intent. Takes are performances of it. Motifs can connect many cues.</p></div>${btn('New cue','new-work','','primary')}</div><div class="wb-work-grid">${works.map(x=>`<article class="wb-panel"><span class="eyebrow">${esc(byId(x.project_id)?.title)}</span><h2>${esc(x.title)}</h2><div class="wb-pills">${pill(nice(x.status),x.take_ids.length?'heard':'intent')}</div><p>${x.take_ids.length?'A listening reference is attached. Original bytes remain unchanged.':'A written direction is preserved. No recording is claimed for this cue.'}</p><div>${btn('Open recipe','open-recipe',`data-id="${x.recipe_id}"`)}${btn('Exact source prompt','source-prompt',`data-id="${x.recipe_id}"`)}</div></article>`).join('')}</div></section></div>`;}
 function experiments(){return `<div class="wb-section-header"><div><h2>ROWAN-001 is a full-performance experiment.</h2><p>Preserve → understand → paint → compose → render → listen → revise. Not simply peak detection.</p></div></div><div class="wb-experiment-grid"><article class="wb-panel"><span class="eyebrow">FIRST STUDY / PLANNED, NOT COMPLETED</span><h2>From a song that moves you to an idea you can work with.</h2><p class="wb-quote">${esc(w().experiments[0]?.question||'No experiment selected.')}</p><div class="wb-check-row">✓ Original WAV preserved by hash</div><div class="wb-check-row">✓ User listening notes and callback links seeded</div><div class="wb-check-row">✓ Raw MIDI retains its original time origin</div><div class="wb-check-row pending">○ Correct the actual performed melody and harmony</div><div class="wb-check-row pending">○ Audition alternate performances on a connected renderer</div><div class="wb-check-row pending">○ Record listening decisions separately from technical tests</div>${btn('Gather full experiment packet','context','data-id="occ_rise"','primary')}</article><article class="wb-panel"><span class="eyebrow">PIPES / EXECUTION CAPABILITY</span><h2>Shared tools. Honest connection states.</h2>${[['Local audio and MIDI','Implemented · measured inventory'],['Story → structured intent','Implemented · deterministic compile'],['Authored MIDI + diagnostic sound','Implemented · sine-tone preview'],['REAPER / realistic instruments','Adapter target · not connected'],['MuseScore / MusicXML','Contract target · not connected'],['Suno and other generators','Manual handoff · no provider calls'],['AOS routing and outbox','Proposed seam · no estate writeback']].map(([a,b])=>`<div class="wb-capability"><b>${a}</b><span>${b}</span></div>`).join('')}<p class="micro">MCP, CLI and browser use the same local commands. Remote auth, provider spend and DAW edits are not enabled by this prototype.</p></article></div><section class="wb-panel wb-history"><h3>Actual local activity</h3>${w().render_jobs.slice(-6).reverse().map(j=>`<p>Diagnostic sketch · ${esc(j.status)} · ${j.duration_seconds.toFixed(1)}s · source ${esc(j.story_id)} r${j.story_revision}</p>`).join('')}${w().packets.slice(-6).reverse().map(p=>`<p>Creation packet · ${esc(p.status)} · ${esc(p.story_id)} r${p.story_revision}</p>`).join('')}${!w().render_jobs.length&&!w().packets.length?'<p>No render or creation packet yet. Preparing a prompt does not mean a song was generated.</p>':''}</section>`;}
 function render(){return `<div class="wb-root">${!w().seeded?welcome():top()+(view==='canvas'?canvas():view==='motifs'?motifs():view==='discover'?discover():view==='projects'?projects():experiments())}</div>`;}
 async function savePatch(patch){const s=current();await api.command('story.update',{story_id:s.id,expected_revision:s.revision,patch},true);api.render();}
 function modal(title,body,footer=''){api.modal(title,body,footer,true);}
 function fieldsOfEvent(){const s=current(),events=structuredClone(s.events),e=events.find(x=>x.id===eventId);e.title=document.querySelector('#wb-event-title').value;e.motif_id=document.querySelector('#wb-event-motif').value;e.instrument=document.querySelector('#wb-event-instrument').value;e.role=document.querySelector('#wb-event-role').value;e.gesture=document.querySelector('#wb-event-gesture').value;e.start=Number(document.querySelector('#wb-event-start').value)/100;e.end=Number(document.querySelector('#wb-event-end').value)/100;e.level=Number(document.querySelector('#wb-event-level').value);e.note=document.querySelector('#wb-event-note').value;return events;}
 async function play(a,b,repeat=false){loop=repeat?{start:a,end:b}:null;previewAudio?.pause();await api.play('take_rowan_original',a,repeat?null:b);}
 async function action(a,el){
  const d=el.dataset;a=a.replace(/^wb-/,'');
  if(a==='seed'){await api.command('workbench.seed',{},true);api.selectReference();api.toast('Rowan imported. Original audio, interpretation and intent are kept separate.');api.render();return;}
  if(a==='view'){view=d.id;api.render();return;}
  if(a==='mode'){mode=d.id;view='canvas';api.render();return;}
  if(a==='project'){project=d.id;api.render();return;}
  if(a==='play'){await play(Number(d.start),Number(d.end));return;}
  if(a==='loop'){await play(Number(d.start),Number(d.end),true);api.toast('Passage looping. Pause playback to stop.');return;}
  if(a==='context-play'){const o=byId(d.id);if(!o)return;const p=byId(o.parent_occurrence_id);await play(p&&p.id!=='occ_full'?p.start:o.start,p&&p.id!=='occ_full'?p.end:o.end);return;}
  if(a==='occurrence'){occId=d.id;view='canvas';mode='heard';api.render();return;}
  if(a==='event'){eventId=d.id;api.render();return;}
  if(a==='save-event'){await savePatch({events:fieldsOfEvent()});api.toast('Gesture saved as a new intent revision. Audio unchanged.');return;}
  if(a==='pin'){const events=structuredClone(current().events);events.find(e=>e.id===eventId).locked=true;await savePatch({events});return;}
  if(a==='unlock'){await api.command('story.unlock',{story_id:current().id,expected_revision:current().revision,event_id:eventId},true);api.render();return;}
  if(a==='add-event'){const s=current(),es=structuredClone(s.events),n=api.newId();es.push({id:'gesture_'+n,title:'A new musical thought',start:.40,end:.57,motif_id:w().motifs[0].id,instrument:'cello',role:'answer',gesture:'answer',level:.5,note:'Describe what this moment should make possible.',locked:false,source_occurrence_id:null,transpose:0});eventId='gesture_'+n;await savePatch({events:es});return;}
  if(a==='link-events'){const es=current().events;modal('Connect two musical thoughts',`<p>A relationship can carry meaning before either gesture has exact notes.</p><label>Later / responding gesture<select id="wb-link-source">${opts(es,eventId)}</select></label><label>Relationship<select id="wb-link-kind">${['recalls','answers','grows_from','supports','withholds','contrasts_with','coincides'].map(x=>`<option value="${x}">${nice(x)}</option>`).join('')}</select></label><label>Earlier / related gesture<select id="wb-link-target">${opts(es,es[0]?.id)}</select></label>`,btn('Save relationship','save-link','','primary'));return;}
  if(a==='save-link'){const get=id=>document.querySelector(id).value;const r={source_id:get('#wb-link-source'),target_id:get('#wb-link-target'),kind:get('#wb-link-kind')};await savePatch({relationships:[...current().relationships,r]});api.closeModal();return;}
  if(a==='new-story'||a==='branch'){modal(a==='branch'?'Branch without losing this version':'An idea before it is a song',`<label>Title<input id="wb-new-title" value="${a==='branch'?esc(current().title+' · variation'):''}" placeholder="A cello answers what the fiddle could not finish"></label><label>Project<select id="wb-new-project">${opts(w().projects,project)}</select></label><p class="micro">A new relative-time draft. Source audio and existing arrangements remain untouched.</p>`,btn('Create story',a==='branch'?'save-branch':'save-story','','primary'));return;}
  if(a==='save-story'||a==='save-branch'){const r=await api.command('story.create',{title:document.querySelector('#wb-new-title').value,project_id:document.querySelector('#wb-new-project').value,...(a==='save-branch'?{source_story_id:current().id}:{})},true);storyId=r.id;eventId=r.events[0]?.id;mode='paint';view='canvas';api.closeModal();api.render();return;}
  if(a==='open-story-event'){storyId=d.story;eventId=d.event;mode='paint';view='canvas';api.render();return;}
  if(a==='capture'){const draft=localStorage.getItem('mm-thought-draft')||'';modal('Keep the spark. It does not have to become a task.',`<label>What are you hearing—or trying to say?<textarea id="wb-capture-text" rows="6" placeholder="That dip is not defeat. It is the weight the next phrase carries.">${esc(draft)}</textarea></label><div class="wb-field-pair"><label>Where<select id="wb-capture-project"><option value="">Unfiled · decide later</option>${opts(w().projects,project)}</select></label><label>Kind<select id="wb-capture-kind">${['idea','listening_interpretation','creative_direction','question','keeper','avoid'].map(x=>`<option value="${x}">${nice(x)}</option>`).join('')}</select></label></div><label>Optional tags<input id="wb-capture-tags" placeholder="longing, cello, home"></label>`,btn('Keep this thought','save-capture','','primary'));document.querySelector('#wb-capture-text').addEventListener('input',e=>localStorage.setItem('mm-thought-draft',e.target.value));return;}
  if(a==='save-capture'){await api.command('capture.create',{text:document.querySelector('#wb-capture-text').value,project_id:document.querySelector('#wb-capture-project').value||null,kind:document.querySelector('#wb-capture-kind').value,tags:document.querySelector('#wb-capture-tags').value.split(',').map(x=>x.trim()).filter(Boolean)},true);localStorage.removeItem('mm-thought-draft');api.closeModal();view='discover';api.render();return;}
  if(a==='search'||a==='search-seed'){query=a==='search'?document.querySelector('#wb-search').value:d.query;results=await api.command('workbench.search',{query,project_id:project});api.render();return;}
  if(a==='result'){if(d.kind==='occurrences'){occId=d.id;mode='heard';view='canvas';api.render();return;}if(d.kind==='stories'){storyId=d.id;mode='paint';view='canvas';api.render();return;}if(d.kind==='works'){api.openRecipe(byId(d.id).recipe_id);return;}await showContext(d.id);return;}
  if(a==='context'){await showContext(d.id);return;}
  if(a==='new-project'){modal('Give a musical world a home',`<label>Name<input id="wb-project-title"></label><label>Inside<select id="wb-project-parent"><option value="">New top-level world</option>${opts(w().projects,project)}</select></label><label>Meaning<textarea id="wb-project-summary" rows="3"></textarea></label>`,btn('Create nested project','save-project','','primary'));return;}
  if(a==='save-project'){const r=await api.command('project.create',{title:document.querySelector('#wb-project-title').value,parent_id:document.querySelector('#wb-project-parent').value||null,summary:document.querySelector('#wb-project-summary').value},true);project=r.id;api.closeModal();api.render();return;}
  if(a==='new-work'){modal('A new cue',`<label>Title<input id="wb-work-title"></label><p>A new recipe is created in the selected project; no recording is implied.</p>`,btn('Create cue','save-work','','primary'));return;}
  if(a==='save-work'){await api.command('work.create',{project_id:project,title:document.querySelector('#wb-work-title').value},true);api.closeModal();api.render();return;}
  if(a==='open-recipe'){api.openRecipe(d.id);return;}
  if(a==='source-prompt'){const r=api.state().recipes.find(r=>r.id===d.id),p=r.source_prompt;modal('Preserved written direction',p?`<p>${esc(p.source_context)} · prompt context, not a verified submission receipt.</p><label>Style<textarea id="wb-prompt-style" rows="6" readonly>${esc(p.style)}</textarea></label><label>Arrangement<textarea id="wb-prompt-lyrics" rows="10" readonly>${esc(p.arrangement)}</textarea></label><label>Shared Exclude<textarea id="wb-prompt-excludes" readonly>${esc(r.excludes)}</textarea></label>`:'<p>No separate source prompt attached. Open the recipe to compile its current direction.</p>',p?`${btn('Copy Style','copy','data-target="wb-prompt-style"')}${btn('Copy arrangement','copy','data-target="wb-prompt-lyrics"')}${btn('Copy Exclude','copy','data-target="wb-prompt-excludes"')}`:'');return;}
  if(a==='new-motif'){modal('A motif may begin as a feeling',`<label>Name<input id="wb-motif-title"></label><label>What it carries<textarea id="wb-motif-meaning" rows="4"></textarea></label><label>Kind<select id="wb-motif-kind">${['melodic','rhythmic_melodic','expressive_arc','harmonic','textural'].map(x=>`<option value="${x}">${nice(x)}</option>`).join('')}</select></label><label>Optional authored MIDI pitches<input id="wb-motif-notes" placeholder="62 66 69 71 69 66"></label><p class="micro">Leave notes blank for a concept. Entered notes are an authored sketch, not a verified transcription. Equal note durations are used initially.</p>`,btn('Keep this motif','save-motif','','primary'));return;}
  if(a==='save-motif'){const notes=document.querySelector('#wb-motif-notes').value.trim();const pitches=notes?notes.split(/[ ,]+/).map(Number):[];await api.command('motif.create',{project_id:project,title:document.querySelector('#wb-motif-title').value,meaning:document.querySelector('#wb-motif-meaning').value,kind:document.querySelector('#wb-motif-kind').value,...(notes?{symbolic:{status:'authored_sketch',pitches,durations:pitches.map(()=>1)}}:{})},true);api.closeModal();api.render();return;}
  if(a==='compile'){const p=await api.command('story.compile',{story_id:current().id});modal('A creation packet—not a generated song',`<div class="notice">${esc(p.prompt.warnings.join(' '))}</div><label>Style <small>${p.prompt.style_count}/1,000 UTF-16 units</small><textarea id="wb-prompt-style" rows="6" readonly>${esc(p.prompt.style)}</textarea></label><label>Instrumental arrangement <small>${p.prompt.lyrics_count}/5,000</small><textarea id="wb-prompt-lyrics" rows="9" readonly>${esc(p.prompt.lyrics)}</textarea></label><label>Exclude<textarea id="wb-prompt-excludes" rows="3" readonly>${esc(p.prompt.excludes)}</textarea></label><p>${p.context.items.length} context records gathered, including explicit dependencies. Source files are not uploaded by preparing this packet.</p>`,`${btn('Copy Style','copy','data-target="wb-prompt-style"')}${btn('Copy arrangement','copy','data-target="wb-prompt-lyrics"')}${btn('Copy Exclude','copy','data-target="wb-prompt-excludes"')}${btn('Freeze local handoff','prepare','','primary')}`);return;}
  if(a==='copy'){await navigator.clipboard.writeText(document.querySelector('#'+d.target).value);api.toast('Copied exact text.');return;}
  if(a==='prepare'){const r=await api.command('story.prepare',{story_id:current().id,expected_revision:current().revision},true);api.closeModal();api.toast('Frozen handoff saved. Nothing submitted; no credits spent.');api.download('music-creation-packet.json',r);api.render();return;}
  if(a==='render-modal'){modal('Bind the sketch to an explicit musical clock',`<p>Only authored or human-verified note representations can render. The accepted Rowan performance still needs corrected notation, so that plan intentionally blocks.</p><div class="wb-field-pair"><label>New draft BPM<input id="wb-render-bpm" type="number" value="80" min="30" max="240"></label><label>Total quarter-note beats<input id="wb-render-beats" type="number" value="48" min="4" max="160"></label></div><p class="micro">This creates MIDI and a quiet sine-tone preview. It neither infers the original tempo nor synthesizes a real fiddle.</p>`,btn('Render local diagnostic','render','','primary'));return;}
  if(a==='render'){const r=await api.command('story.render',{story_id:current().id,expected_revision:current().revision,bpm:Number(document.querySelector('#wb-render-bpm').value),total_beats:Number(document.querySelector('#wb-render-beats').value)},true);lastRender=r;api.closeModal();api.render();api.toast('Authored MIDI and diagnostic audio rendered locally.');return;}
 }
 async function showContext(id){const p=await api.command('workbench.context',{ids:[id],project_id:project});modal('The materials—and why they belong together',`<p>${p.items.length} connected records. Selected passage → enclosing phrase → earlier callback → source and motif lineage.</p><div class="wb-context-list">${p.items.map(x=>`<article><strong>${esc(x.record.title||x.record.text?.slice(0,70)||x.id)}</strong><small>${esc(x.included_because)}</small><p>${esc(x.record.note||x.record.meaning||x.record.summary||x.record.notes||'')}</p></article>`).join('')}</div><p class="micro">${esc(p.rules.join(' '))}</p>`,btn('Export this packet','download-context','','primary'));document.querySelector('[data-action="wb-download-context"]').addEventListener('click',e=>{e.stopPropagation();api.download('music-context.json',p);});}
 function afterRender(){
  if(w().seeded&&!ref&&!refLoading){refLoading=true;api.command('workbench.reference',{}).then(r=>{ref=r;api.render();}).catch(e=>api.toast(e.message,true)).finally(()=>refLoading=false);}
  document.querySelector('#wb-story-select')?.addEventListener('change',e=>{storyId=e.target.value;eventId=current()?.events[0]?.id;lastRender=null;api.render();});
  document.querySelector('#wb-search')?.addEventListener('keydown',e=>{if(e.key==='Enter')action('wb-search',{dataset:{}}).catch(e=>api.toast(e.message,true));});
  const svg=document.querySelector('.wb-story-svg');if(svg){let drag=null;svg.addEventListener('pointerdown',ev=>{const g=ev.target.closest('[data-stroke-id]');if(!g)return;const e=current().events.find(e=>e.id===g.dataset.strokeId);if(e?.locked)return;drag={id:e.id,client:ev.clientX,start:e.start,end:e.end,g,original:g.getAttribute('transform'),moved:false};svg.setPointerCapture(ev.pointerId);});svg.addEventListener('pointermove',ev=>{if(!drag)return;const dx=(ev.clientX-drag.client)/svg.getBoundingClientRect().width*1000;drag.moved=Math.abs(dx)>3;drag.dx=dx;drag.g.setAttribute('transform',drag.original+` translate(${dx},0)`);});svg.addEventListener('pointerup',ev=>{if(!drag)return;const d=drag;drag=null;if(!d.moved)return;const es=structuredClone(current().events),e=es.find(e=>e.id===d.id),len=e.end-e.start;e.start=Math.min(1-len,Math.max(0,e.start+(d.dx||0)/825));e.end=e.start+len;e.start=Math.round(e.start*1000)/1000;e.end=Math.round(e.end*1000)/1000;eventId=e.id;savePatch({events:es}).catch(err=>{api.toast(err.message,true);api.render();});});}
  previewAudio=document.querySelector('#wb-preview-audio');previewAudio?.addEventListener('play',()=>{loop=null;api.audio.pause();});
 }
 api.audio.addEventListener('timeupdate',()=>{if(api.audio.dataset.take==='take_rowan_original'){const t=api.audio.currentTime,wh=document.querySelector('#wb-wave-head'),mh=document.querySelector('#wb-midi-head');if(wh){wh.setAttribute('x1',20+t/194.8*960);wh.setAttribute('x2',20+t/194.8*960);wh.setAttribute('opacity','1');}if(mh){mh.setAttribute('x1',50+(t-85)/27*930);mh.setAttribute('x2',50+(t-85)/27*930);mh.setAttribute('opacity',t>=85&&t<=112?'1':'0');}}if(loop&&api.audio.currentTime>=loop.end){api.audio.currentTime=loop.start;api.audio.play().catch(()=>{});}});
 api.audio.addEventListener('pause',()=>{if(loop&&api.audio.currentTime<loop.end-.2)loop=null;});
 return {render,action,afterRender};
}
